// The DSA indexer's paged fp8 logits on gfx950 for 32 heads of 128 and pages of 64 keys in aiter's
// preshuffled layout: logits[r, t] = scale_t * sum_h weights[r, h] * relu(q[r, h] . key_t) over the
// keys of row r's pages, -inf in its last page from context_lens[r] on, the pages past it untouched.
// A block holds up to ROWS rows' queries and weights in LDS; each wave walks page columns, loads a page
// once for consecutive rows that name it (MTP verify's rows share their request's pages) and scores it
// with 16 x 16 x 128 fp8 MFMAs; contexts short enough take a wave a (column, row) instead.
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>

namespace dsa_logits {
namespace {

constexpr int PAGE       = 64;
constexpr int HEAD_DIM   = 128;
constexpr int HEADS      = 32;
constexpr int K_BYTES    = PAGE * HEAD_DIM;  // the page's keys, then a float scale per key
constexpr int PAGE_BYTES = K_BYTES + PAGE * 4;
constexpr int Q_BYTES    = HEADS * HEAD_DIM;
constexpr int Q_PITCH    = HEAD_DIM + 16;  // a head's bytes in LDS, padded off the 16 heads' banks
constexpr int ROWS       = 6;  // rows a block scores at most: a request's MTP verify rows
constexpr int WAVES      = 8;
constexpr int CHUNK      = 8;  // columns whose pages a wave looks up at once, 8 rows each
constexpr int SPREAD     = 2;   // entries a wave scores at most where each loads its own page
constexpr int SPECULATE  = 64;  // waves of a row group that load their first entry's query up front

typedef int   i32x4 __attribute__((ext_vector_type(4)));
typedef int   i32x8 __attribute__((ext_vector_type(8)));
typedef float f32x4 __attribute__((ext_vector_type(4)));
typedef float f32x2 __attribute__((ext_vector_type(2)));

union V8 {
    i32x8 v;
    i32x4 h[2];
};

__device__ __forceinline__ f32x4 mfma(i32x8 a, i32x8 b) {
    const f32x4 zero = {0.f, 0.f, 0.f, 0.f};
    // e4m3 operands, unit block scales
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, zero, 0, 0, 0, 127, 0, 127);
}

// lane l reads lane l ^ 32, l ^ 16
__device__ __forceinline__ float xor32(float x, int lane) {
    const int v = __builtin_bit_cast(int, x);
    const auto r = __builtin_amdgcn_permlane32_swap(v, v, false, false);
    return __builtin_bit_cast(float, (lane & 32) ? r[0] : r[1]);
}
__device__ __forceinline__ float xor16(float x, int lane) {
    const int v = __builtin_bit_cast(int, x);
    const auto r = __builtin_amdgcn_permlane16_swap(v, v, false, false);
    return __builtin_bit_cast(float, (lane & 16) ? r[0] : r[1]);
}

struct Params {
    const uint8_t *q;    // [batch, HEADS, HEAD_DIM] e4m3
    const uint8_t *kv;   // [n_pages, PAGE_BYTES]
    const float   *w;    // [batch, HEADS]
    const int     *lens; // [batch]
    const int     *table; // [batch, max_blocks]
    float         *out;  // [batch, max_blocks * PAGE]
    int            batch;
    int            max_blocks;
    int            rows;  // rows a block scores, at most ROWS
};

// the page's 16-key groups: [8 blocks of 16 dims][16 keys][16 dims], then a scale per key
__device__ __forceinline__ void load_page(const Params &p, int page, int koff, int lane, V8 (&b)[4],
                                          float &scale) {
    const uint8_t *base = p.kv + static_cast<size_t>(page) * PAGE_BYTES;
#pragma unroll
    for (int t = 0; t < 4; ++t) {
        b[t].h[0] = *reinterpret_cast<const i32x4 *>(base + koff + t * 2048);
        b[t].h[1] = *reinterpret_cast<const i32x4 *>(base + koff + t * 2048 + 256);
    }
    scale = reinterpret_cast<const float *>(base + K_BYTES)[lane];
}

// the page of row lane & 7 at column col, -1 past the table or the row's context; the table entry loads
// whatever the context, so that the load does not wait for it
__device__ __forceinline__ int page_at(const Params &p, const int *table, int nrows, int col, int lane, int len) {
    const int r    = lane & 7;
    const int page = col < p.max_blocks && r < nrows ? table[static_cast<size_t>(r) * p.max_blocks + col] : -1;
    return col * PAGE < len ? page : -1;
}

// a row's query operands and weights, from q (a head every pitch bytes) and w: lane (c, g) holds heads c
// and 16 + c over dims [32g, 32g + 32), and the weights of heads 4g .. 4g + 3 and 16 + 4g ..
__device__ __forceinline__ void row_query(const uint8_t *q, int pitch, const float *w, int lane, V8 &q0, V8 &q1,
                                          f32x4 &w0, f32x4 &w1) {
    const int      g = lane >> 4, c = lane & 15;
    const uint8_t *qr = q + c * pitch + g * 32;
    q0.h[0] = *reinterpret_cast<const i32x4 *>(qr);
    q0.h[1] = *reinterpret_cast<const i32x4 *>(qr + 16);
    q1.h[0] = *reinterpret_cast<const i32x4 *>(qr + 16 * pitch);
    q1.h[1] = *reinterpret_cast<const i32x4 *>(qr + 16 * pitch + 16);
    w0      = *reinterpret_cast<const f32x4 *>(w + g * 4);
    w1      = *reinterpret_cast<const f32x4 *>(w + 16 + g * 4);
}

// a[2t], a[2t + 1]: heads 4g .. 4g + 3 and 16 + 4g .. of key c of the page's group t, all issued before
// any is used
__device__ __forceinline__ void page_mfmas(const V8 &q0, const V8 &q1, const V8 (&b)[4], f32x4 (&a)[8]) {
#pragma unroll
    for (int t = 0; t < 4; ++t) {
        a[2 * t]     = mfma(q0.v, b[t].v);
        a[2 * t + 1] = mfma(q1.v, b[t].v);
    }
}

// the weighted relu sum over the heads of a's keys, with halved weights (relu(x) w is (x + |x|) w / 2,
// exactly), summed over the four g's of each key so that lane l ends with key l of the page
__device__ __forceinline__ float page_logits(const f32x4 (&a)[8], f32x4 w0, f32x4 w1, int lane) {
    const int g = lane >> 4;
    float     s[4];
#pragma unroll
    for (int t = 0; t < 4; ++t) {
        f32x2 acc = {0.f, 0.f};
#pragma unroll
        for (int h = 0; h < 2; ++h) {
            const f32x4 x = a[2 * t + h], w = h ? w1 : w0;
#pragma unroll
            for (int j = 0; j < 4; j += 2) {
                const f32x2 v = {x[j] + __builtin_fabsf(x[j]), x[j + 1] + __builtin_fabsf(x[j + 1])};
                acc           = __builtin_elementwise_fma(v, (f32x2){w[j], w[j + 1]}, acc);
            }
        }
        s[t] = acc[0] + acc[1];
    }
    const bool  hi = (g & 2) != 0, odd = (g & 1) != 0;
    const float a0 = (hi ? s[2] : s[0]) + xor32(hi ? s[0] : s[2], lane);
    const float a1 = (hi ? s[3] : s[1]) + xor32(hi ? s[1] : s[3], lane);
    return (odd ? a1 : a0) + xor16(odd ? a0 : a1, lane);
}

__global__ __launch_bounds__(WAVES * 64) void logits_kernel(Params p) {
    __shared__ __attribute__((aligned(16))) uint8_t s_q[ROWS][HEADS * Q_PITCH];
    __shared__ __attribute__((aligned(16))) float   s_w[ROWS][HEADS];

    const int  row0   = blockIdx.x * p.rows;
    const int  nrows  = min(p.rows, p.batch - row0);
    const int  lane   = threadIdx.x & 63;
    const int  koff   = (lane >> 4) * 512 + (lane & 15) * 16;
    const int  stride = p.max_blocks * PAGE;
    const int *table  = p.table + static_cast<size_t>(row0) * p.max_blocks;
    float     *out    = p.out + static_cast<size_t>(row0) * stride;
    const int waves = gridDim.y * WAVES;
    const int wave  = __builtin_amdgcn_readfirstlane(blockIdx.y * WAVES + (threadIdx.x >> 6));
    // the wave's first entry (column, row): its page, and for the first SPECULATE waves, those a short
    // context keeps busy, its row's query and weights, load alongside the contexts, whatever they are, so
    // that none waits for them (the rest would only crowd the busy waves' loads); the asm holds them
    // there, else the compiler sinks them past the contexts, a round trip later
    const int col0 = wave / nrows, r0 = wave % nrows;
    int       page = col0 < p.max_blocks ? table[static_cast<size_t>(r0) * p.max_blocks + col0] : 0;
    V8        q0{}, q1{};
    f32x4     w0{}, w1{};
    if (wave < SPECULATE)
        row_query(p.q + static_cast<size_t>(row0 + r0) * Q_BYTES, HEAD_DIM,
                  p.w + static_cast<size_t>(row0 + r0) * HEADS, lane, q0, q1, w0, w1);
    // lane 8k + r: row r's context; the pages of the longest
    const int len = (lane & 7) < nrows ? p.lens[row0 + (lane & 7)] : 0;
    asm volatile("" ::"v"(page), "v"(q0.v), "v"(q1.v), "v"(w0), "v"(w1));
    int longest = len;
    for (int o = 1; o < 8; o <<= 1) longest = max(longest, __shfl_xor(longest, o));

    // Contexts of at most SPREAD entries a wave: entries wave, wave + waves, ..., so that their pages
    // spread over all the waves, each loading its row's query itself
    const int entries = (longest + PAGE - 1) / PAGE * nrows;
    if (entries <= SPREAD * waves) {
        for (int e = wave; e < entries; e += waves) {
            const int col = e / nrows, r = e % nrows, n = __builtin_amdgcn_readlane(len, r);
            if (e != wave || wave >= SPECULATE) {
                page = table[static_cast<size_t>(r) * p.max_blocks + col];
                row_query(p.q + static_cast<size_t>(row0 + r) * Q_BYTES, HEAD_DIM,
                          p.w + static_cast<size_t>(row0 + r) * HEADS, lane, q0, q1, w0, w1);
            }
            if (col * PAGE >= n) continue;
            V8    b[4];
            float sc;
            f32x4 a[8];
            load_page(p, page, koff, lane, b, sc);
            // every load in flight before the first MFMA waits: left alone the scheduler splits them
            // around the MFMAs into two or three round trips
            __builtin_amdgcn_sched_barrier(0);
            // and every MFMA issued before the first result is read, each into its own registers
            page_mfmas(q0, q1, b, a);
            __builtin_amdgcn_sched_barrier(0);
            const float total = page_logits(a, 0.5f * w0, 0.5f * w1, lane);
            out[static_cast<size_t>(r) * stride + col * PAGE + lane] = col * PAGE + lane < n ? total * sc : -INFINITY;
        }
        return;
    }

    // Longer ones: the wave's columns, every waves-th from its own, so that a short context spreads over
    // many waves; a chunk is CHUNK of them, lane 8k + r holding row r's page of the k-th, and a page loads
    // once for the rows of the block that name it
    auto col_of = [&](int base, int k) { return wave + (base + k) * waves; };
    // the pages of the wave's first chunk, and the first of them, load while the block stages the
    // queries and weights; a block whose first column is past every row's context has none
    int pages = page_at(p, table, nrows, col_of(0, lane >> 3), lane, len);
    if (!__syncthreads_or(len > static_cast<int>(blockIdx.y) * WAVES * PAGE)) return;
    V8    bc[4], bn[4];  // the page being scored, and the next one loading meanwhile
    float sc = 0.f, sn = 0.f;
    const uint64_t first = __ballot(pages >= 0);
    int            hc    = first ? __builtin_amdgcn_readlane(pages, __builtin_ctzll(first)) : -1, hn = -1;
    if (hc >= 0) load_page(p, hc, koff, lane, bc, sc);

    for (int i = threadIdx.x; i < nrows * Q_BYTES / 16; i += WAVES * 64) {
        const int head = i / (HEAD_DIM / 16), chunk = i % (HEAD_DIM / 16);
        *reinterpret_cast<i32x4 *>(&s_q[0][head * Q_PITCH + chunk * 16]) =
            reinterpret_cast<const i32x4 *>(p.q + static_cast<size_t>(row0) * Q_BYTES)[i];
    }
    // halved, for page_logits
    for (int i = threadIdx.x; i < nrows * HEADS; i += WAVES * 64)
        s_w[i / HEADS][i % HEADS] = 0.5f * p.w[static_cast<size_t>(row0) * HEADS + i];
    __syncthreads();

    for (int base = 0; col_of(base, 0) < p.max_blocks; base += CHUNK) {
        // the entries (columns of the chunk x rows) whose page is scored
        uint64_t  live       = __ballot(pages >= 0);
        const int next_pages = page_at(p, table, nrows, col_of(base + CHUNK, lane >> 3), lane, len);
#pragma unroll 1
        for (; live; live &= live - 1) {
            const int i = __builtin_ctzll(live), r = i & 7, col = col_of(base, i >> 3);
            const int page = __builtin_amdgcn_readlane(pages, i);
            if (page != hc) {
                if (page == hn) {
#pragma unroll
                    for (int t = 0; t < 4; ++t) bc[t] = bn[t];
                    sc = sn;
                } else {
                    load_page(p, page, koff, lane, bc, sc);
                }
                hc = page;
            }
            V8    q0, q1;
            f32x4 w0, w1, a[8];
            row_query(s_q[r], Q_PITCH, s_w[r], lane, q0, q1, w0, w1);
            page_mfmas(q0, q1, bc, a);
            // the next page scored, the chunk's next live entry's else the next chunk's first, loads
            // once this one's scales are in: a wait for them must not wait for it
            asm volatile("" ::"v"(sc));
            const uint64_t rest  = live & (live - 1);
            const uint64_t ahead = rest ? 0 : __ballot(next_pages >= 0);
            const int      next  = rest    ? __builtin_amdgcn_readlane(pages, __builtin_ctzll(rest))
                                   : ahead ? __builtin_amdgcn_readlane(next_pages, __builtin_ctzll(ahead))
                                           : -1;
            if (next >= 0 && next != hc && next != hn) {
                load_page(p, next, koff, lane, bn, sn);
                hn = next;
            }
            const float total = page_logits(a, w0, w1, lane);
            out[static_cast<size_t>(r) * stride + col * PAGE + lane] =
                col * PAGE + lane < __builtin_amdgcn_readlane(len, r) ? total * sc : -INFINITY;
        }
        pages = next_pages;
    }
}

void run(const at::Tensor &q, const at::Tensor &kv_cache, const at::Tensor &weights,
         const at::Tensor &context_lens, const at::Tensor &block_tables, at::Tensor &logits,
         int64_t page_size, bool preshuffled) {
    TORCH_CHECK(page_size == PAGE && preshuffled && q.size(1) == 1 && q.size(2) == HEADS,
                "preshuffled pages of 64 keys, one query of 32 heads a row only");
    TORCH_CHECK(q.is_contiguous() && kv_cache.is_contiguous() && weights.is_contiguous() &&
                    context_lens.is_contiguous() && block_tables.is_contiguous() &&
                    logits.is_contiguous(),
                "contiguous tensors only");
    const int batch      = static_cast<int>(q.size(0));
    const int max_blocks = static_cast<int>(block_tables.size(1));
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(q.device());
    Params p{};
    p.q          = static_cast<const uint8_t *>(q.data_ptr());
    p.kv         = kv_cache.data_ptr<uint8_t>();
    p.w          = weights.data_ptr<float>();
    p.lens       = context_lens.data_ptr<int>();
    p.table      = block_tables.data_ptr<int>();
    p.out        = logits.data_ptr<float>();
    p.batch      = batch;
    p.max_blocks = max_blocks;
    // the rows of a block are a request's MTP verify rows, GLM-5.3's 6, which share their pages (else a
    // row, sharing none); the blocks along the columns as many as give each entry of the widest context
    // a wave, up to two a CU in all (its registers hold two), so that one round runs them all; the row
    // groups the fast axis, so that the first column blocks, a short context's, start first
    const int cus    = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    p.rows           = batch % 6 == 0 ? 6 : 1;
    const int groups = (batch + p.rows - 1) / p.rows;
    const int cols   = std::min((max_blocks * p.rows + WAVES - 1) / WAVES, std::max(1, 2 * cus / groups));
    const dim3 grid(groups, cols);
    hipLaunchKernelGGL(logits_kernel, grid, dim3(WAVES * 64), 0, at::hip::getCurrentHIPStream(), p);
    C10_HIP_CHECK(hipGetLastError());
}

} // namespace
} // namespace dsa_logits

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor q, Tensor kv_cache, Tensor weights, Tensor context_lens, Tensor block_tables, "
          "Tensor(a!) logits, int page_size, bool preshuffled) -> ()",
          &dsa_logits::run);
}
